-- Vacancy module (vacancy.db)
-- Open vacancies, applications and interviews.
-- Generated by Migrations/build_module_databases.py --refresh-schema;
-- foreign keys into another module's file are dropped on purpose.

CREATE TABLE "job_vacancies" (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        reference TEXT,
        job_title TEXT NOT NULL,
        department TEXT NOT NULL,
        department_id INTEGER,
        job_type TEXT NOT NULL DEFAULT 'Full-time',
        location TEXT DEFAULT '',
        description TEXT DEFAULT '',
        requirements TEXT DEFAULT '',
        openings INTEGER NOT NULL DEFAULT 1,
        minimum_gpa REAL NOT NULL DEFAULT 0,
        minimum_age INTEGER NOT NULL DEFAULT 0,
        maximum_age INTEGER NOT NULL DEFAULT 0,
        internal_only INTEGER NOT NULL DEFAULT 0,
        estimated_cost REAL NOT NULL DEFAULT 0,
        budget_allocation_id INTEGER,
        approval_request_id INTEGER,
        created_by_id INTEGER,
        created_by_name TEXT DEFAULT '',
        hired_count INTEGER NOT NULL DEFAULT 0,
        closing_date TEXT,
        status TEXT NOT NULL DEFAULT 'Open' CHECK (status IN ('Draft', 'Open', 'Closed')),
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_by INTEGER, updated_by_name TEXT, updated_at TEXT);

CREATE TABLE job_applications (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                vacancy_id INTEGER NOT NULL,
                full_name TEXT NOT NULL,
                email TEXT NOT NULL,
                phone TEXT NOT NULL,
                education TEXT DEFAULT '',
                experience TEXT DEFAULT '',
                resume_filename TEXT DEFAULT '',
                cover_letter TEXT DEFAULT '',
                status TEXT NOT NULL DEFAULT 'Applied'
                    CHECK (status IN (
                        'Applied', 'Shortlisted', 'Interview',
                        'Selected', 'Rejected', 'Hired'
                    )),
                applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, reference TEXT, user_id INTEGER, date_of_birth TEXT, age INTEGER, gpa REAL, source TEXT NOT NULL DEFAULT 'Portal', screened_by_id INTEGER, screened_by_name TEXT DEFAULT '', screened_at TEXT, decision_note TEXT DEFAULT '', updated_by INTEGER, updated_by_name TEXT, updated_at TEXT, employee_id INTEGER, hired_at TEXT,
                FOREIGN KEY (vacancy_id) REFERENCES job_vacancies(id)
            );

CREATE TABLE recruitment_interviews (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        vacancy_id INTEGER NOT NULL,
        application_id INTEGER NOT NULL,
        scheduled_at TEXT,
        location TEXT DEFAULT '',
        note TEXT DEFAULT '',
        status TEXT NOT NULL DEFAULT 'Scheduled'
            CHECK (status IN ('Scheduled', 'Held', 'Cancelled')),
        outcome TEXT NOT NULL DEFAULT 'Pending' CHECK (outcome IN ('Pending', 'Passed', 'Failed', 'Withdrew')),
        created_by_id INTEGER,
        created_by_name TEXT DEFAULT '',
        created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_by INTEGER, updated_by_name TEXT, updated_at TEXT,
        FOREIGN KEY (vacancy_id) REFERENCES job_vacancies(id),
        FOREIGN KEY (application_id) REFERENCES job_applications(id));

CREATE TABLE interview_panel (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        interview_id INTEGER NOT NULL,
        panel_user_id INTEGER NOT NULL,
        panel_user_name TEXT DEFAULT '',
        added_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (interview_id) REFERENCES recruitment_interviews(id)
            ON DELETE CASCADE,
        UNIQUE (interview_id, panel_user_id)
    );

CREATE TABLE interview_scores (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        interview_id INTEGER NOT NULL,
        panel_user_id INTEGER NOT NULL,
        panel_user_name TEXT DEFAULT '',
        score REAL NOT NULL DEFAULT 0 CHECK (score >= 0),
        recommendation TEXT NOT NULL DEFAULT 'Hold'
            CHECK (recommendation IN ('Hire', 'Hold', 'No hire')),
        comment TEXT DEFAULT '',
        recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (interview_id) REFERENCES recruitment_interviews(id)
            ON DELETE CASCADE,
        UNIQUE (interview_id, panel_user_id)
    );

CREATE INDEX idx_vacancies_department ON job_vacancies (department_id, status);
CREATE INDEX idx_vacancies_reference ON job_vacancies (reference);
CREATE INDEX idx_applications_email ON job_applications (email);
CREATE INDEX idx_applications_employee ON job_applications (employee_id);
CREATE INDEX idx_applications_user ON job_applications (user_id, applied_at);
CREATE INDEX idx_applications_vacancy ON job_applications (vacancy_id, status);
CREATE INDEX idx_interviews_application ON recruitment_interviews (application_id);
CREATE INDEX idx_scores_interview ON interview_scores (interview_id);
